steps.prompt_template:
Analizza questo stipendio e rispondi SOLO con un JSON valido:

Ruolo: {{1.ruolo}}
Località: {{1.localita}}
Stipendio annuo: {{1.stipendio}} EUR
Anni esperienza: {{1.anni_esperienza}}

Rispondi con questo formato JSON:
{
  "score": 1-5 (1=molto sotto media, 3=in media, 5=molto sopra media),
  "rationale": "Spiegazione breve e chiara"
}

JSON:

steps.code:
// Pulisci e parsa la risposta AI
let text = inputData.ai_response || '';

// Rimuovi markdown se presente
text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

try {
  const parsed = JSON.parse(text);
  output = {
    score: Number(parsed.score) || 3,
    rationale: String(parsed.rationale || 'Analisi non disponibile')
  };
} catch (e) {
  // Fallback
  output = {
    score: 3,
    rationale: 'Analisi in corso, riprova tra qualche minuto.'
  };
}
